node -e "
const Database = require('better-sqlite3');
const crypto = require('crypto');
const db = new Database('/workspace/world.db');

const messageId = crypto.randomUUID();
const now = Math.floor(Date.now() / 1000);
const nowISO = new Date().toISOString().replace(/\.\d+Z$/, '');

db.prepare(\`
  INSERT INTO ts_messages (message_id, sender_person_id, sender_phone_number, recipient_person_id, recipient_phone_number, content, creation_timestamp, created_at)
  VALUES (?, ?, ?, ?, ?, ?, ?, ?)
\`).run(
  messageId,
  '2886d614-b329-4b5b-9bae-aedf8a1fff0d',
  '+1-415-555-0187',
  '3f77f374-b93a-4b7d-9982-dddabd4d8150',
  '+1-347-555-0169',
  'Hi Daniel, just confirming the apartment cleaning tomorrow between 2 and 4 PM. See you then!',
  now,
  nowISO
);

const msg = db.prepare('SELECT * FROM ts_messages WHERE message_id = ?').get(messageId);
console.log(JSON.stringify(msg, null, 2));
"
